/* AT AI Mobil — F60.94.31.34
   Restores the original Yıllık Yarış Arşivi UI while replacing its planned annual-program source
   with TJK Koşu Sorgulama (actual races). Race-number resolution uses actual daily results. */
(()=>{
'use strict';
if(window.__AT_ANNUAL_QUERY_SOURCE_F60943134__)return;
window.__AT_ANNUAL_QUERY_SOURCE_F60943134__=true;
const VERSION='F60.94.31.34 · ANNUAL-QUERY-SOURCE';
const DB='at_ai_tjk_annual_archive_v13',DBVER=3,RACES='races',META='meta';
const PAGE_SIZE=50,CONCURRENCY=4;
const CITY_IDS={ADANA:1,IZMIR:2,ISTANBUL:3,BURSA:4,ANKARA:5,SANLIURFA:6,ELAZIG:7,DIYARBAKIR:8,KOCAELI:9,ANTALYA:10};
const clean=v=>String(v??'').replace(/\u00a0/g,' ').replace(/\s+/g,' ').trim();
const upper=v=>clean(v).toLocaleUpperCase('tr-TR').normalize('NFKD').replace(/[\u0300-\u036f]/g,'');
const norm=v=>upper(v).replace(/İ/g,'I').replace(/[^A-Z0-9]+/g,' ').trim();
const key=v=>norm(v).replace(/\s+/g,'');
const trackKey=v=>{const t=upper(v);if(t.includes('CIM'))return'CIM';if(t.includes('KUM'))return'KUM';if(t.includes('SENTETIK'))return'SENTETIK';return key(v)};
const ageKey=v=>key(v);
const cityId=city=>CITY_IDS[key(city)]||'';
function parseClass(raw=''){
  const parts=clean(raw).replace(/\s*\/\s*/g,'/').split('/').map(clean).filter(Boolean),base=parts.shift()||'';
  const tokens=parts.map(x=>upper(x).replace(/\s+/g,'').replace(/^\/+|\/+$/g,'').replace(/İ/g,'I')).filter(Boolean).sort((a,b)=>a.localeCompare(b,'tr'));
  let classKey=`${key(base)}${tokens.length?'/'+tokens.join('/'):''}`;
  try{if(typeof window.canonicalClassKeyV125==='function')classKey=window.canonicalClassKeyV125(raw)||classKey}catch{}
  return{base,tokens,classKey};
}
function status(text,pct=null){const s=document.getElementById('aaUpdateStatus');if(s)s.textContent=text;const b=document.getElementById('aaProgressBar');if(b&&pct!==null)b.style.width=Math.max(0,Math.min(100,Number(pct)||0))+'%'}
function renameMenu(){const b=document.getElementById('annualArchiveBtn');if(b)b.textContent='7. Yıllık Yarış Arşivi';const h=document.querySelector('#tjkAnnualArchiveDialog h2');if(h)h.textContent='TJK Yıllık Yarış Arşivi';const u=document.getElementById('aaUpdateYear');if(u)u.textContent='Seçili Yılı Koşu Sorgulamadan Güncelle'}
function openDb(){return new Promise(resolve=>{let q;try{q=indexedDB.open(DB,DBVER)}catch{return resolve(null)}q.onsuccess=()=>resolve(q.result);q.onerror=q.onblocked=()=>resolve(null)})}
async function replaceYear(year,rows){const db=await openDb();if(!db)throw new Error('Yıllık arşiv veritabanı açılamadı.');await new Promise((resolve,reject)=>{try{const tx=db.transaction(RACES,'readwrite'),os=tx.objectStore(RACES),idx=os.indexNames.contains('year')?os.index('year'):null,q=idx?idx.openCursor(IDBKeyRange.only(Number(year))):os.openCursor();q.onsuccess=()=>{const c=q.result;if(!c)return;const v=c.value?.value||{},y=Number(v.year||String(v.date||'').slice(0,4));if(idx||y===Number(year))c.delete();c.continue()};q.onerror=()=>{try{tx.abort()}catch{}};tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(tx.error||new Error('Eski yıl arşivi temizlenemedi.'))}catch(e){reject(e)}});
  const batch=250;for(let i=0;i<rows.length;i+=batch){const part=rows.slice(i,i+batch);await new Promise((resolve,reject)=>{try{const tx=db.transaction(RACES,'readwrite'),os=tx.objectStore(RACES),now=Date.now();for(const row of part)os.put({key:row.id,value:row,updatedAt:now});tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(tx.error||new Error('Yarışlar yazılamadı.'))}catch(e){reject(e)}});status(`${year}: ${Math.min(i+part.length,rows.length)}/${rows.length} gerçekleşmiş yarış kaydedildi…`,92+Math.round(Math.min(i+part.length,rows.length)/Math.max(1,rows.length)*7));await new Promise(r=>requestAnimationFrame(r))}
  await new Promise((resolve,reject)=>{try{const tx=db.transaction(META,'readwrite');tx.objectStore(META).put({key:`year:${year}`,value:{year:Number(year),status:'complete',recordCount:rows.length,totalReported:rows.length,source:'TJK_KOSU_SORGULAMA',updatedAt:new Date().toISOString(),version:VERSION},updatedAt:Date.now()});tx.oncomplete=resolve;tx.onerror=tx.onabort=()=>reject(tx.error||new Error('Yıl özeti yazılamadı.'))}catch(e){reject(e)}});try{db.close()}catch{}
}
async function putRow(row){const db=await openDb();if(!db)return false;return new Promise(resolve=>{try{const tx=db.transaction(RACES,'readwrite');tx.objectStore(RACES).put({key:row.id,value:row,updatedAt:Date.now()});tx.oncomplete=()=>{try{db.close()}catch{}resolve(true)};tx.onerror=tx.onabort=()=>{try{db.close()}catch{}resolve(false)}}catch{try{db.close()}catch{}resolve(false)}})}
async function fetchJson(url){const r=await fetch(url,{cache:'no-store',headers:{accept:'application/json'}});let d=null;try{d=await r.json()}catch{}if(!r.ok||d?.ok===false)throw new Error(d?.error||`API ${r.status}`);return d}
async function mapLimit(items,limit,worker){const out=new Array(items.length);let cursor=0;async function run(){for(;;){const i=cursor++;if(i>=items.length)return;out[i]=await worker(items[i],i)}}await Promise.all(Array.from({length:Math.min(limit,items.length||1)},run));return out}
function currentEnd(year){const n=new Date(),today=`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,'0')}-${String(n.getDate()).padStart(2,'0')}`;return Number(year)===n.getFullYear()?today:`${year}-12-31`}
function queryUrl(year,page){const u=new URL('/api/tjk-race-query-v1',location.origin);u.searchParams.set('start',`${year}-01-01`);u.searchParams.set('end',currentEnd(year));u.searchParams.set('page',String(page));u.searchParams.set('_at',String(Date.now()));return u.pathname+u.search}
function toArchiveRow(q,page,rowIndex){const date=clean(q?.date),city=clean(q?.city),groupRaw=clean(q?.group||q?.ageGroup),classRaw=clean(q?.raceType||q?.class),distance=Number(q?.distance||0),track=clean(q?.track);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!city||!groupRaw||!classRaw||!distance||!track)return null;const pc=parseClass(classRaw),prize=Number(q?.prize);return{date,year:Number(date.slice(0,4)),city,cityId:String(cityId(city)),groupRaw,classRaw,classBase:pc.base,classBaseKey:key(pc.base),classKey:pc.classKey,extraTokens:pc.tokens,distance,track,trackKey:trackKey(track),prizeRaw:Number.isFinite(prize)?String(prize):'',prizeValue:Number.isFinite(prize)?prize:null,raceName:clean(q?.raceName||''),page:Number(page)||0,rowIndex:Number(rowIndex)||0,raceNo:0,queryRaceNoHint:Number(q?.raceNo||0)||0,queryWinner:clean(q?.winner||''),queryWinnerDegree:clean(q?.winnerDegree||''),source:'TJK_KOSU_SORGULAMA',sourceKey:clean(q?.key||q?.canonicalRaceId||'')}}
function finalize(rows,year){const seen=new Map(),out=[];for(const r of rows){if(!r||Number(r.year)!==Number(year))continue;const base=[r.date,r.cityId,ageKey(r.groupRaw),key(r.classRaw),r.distance,trackKey(r.track),clean(r.prizeRaw),key(r.raceName),key(r.queryWinner)].join('|'),occ=(seen.get(base)||0)+1;seen.set(base,occ);out.push({...r,occurrenceIndex:occ,id:`${base}|${occ}`})}return out}
async function updateYearFromQuery(year){const y=Number(year);if(!y)return;const btn=document.getElementById('aaUpdateYear');if(btn)btn.disabled=true;try{status(`${y} Koşu Sorgulama ilk sayfa alınıyor…`,2);const first=await fetchJson(queryUrl(y,0)),firstRows=Array.isArray(first?.rows)?first.rows:[],expected=Number(first?.total||firstRows.length||0);if(!firstRows.length&&!expected)throw new Error('Koşu Sorgulama bu yıl için gerçekleşmiş yarış döndürmedi.');const pages=Math.max(1,Math.ceil(Math.max(expected,firstRows.length)/PAGE_SIZE)),pageNos=Array.from({length:Math.max(0,pages-1)},(_,i)=>i+1);let done=1;const rest=await mapLimit(pageNos,CONCURRENCY,async p=>{const d=await fetchJson(queryUrl(y,p));done++;status(`${y}: Koşu Sorgulama ${done}/${pages} sayfa…`,Math.round(done/pages*88));return{page:p,rows:Array.isArray(d?.rows)?d.rows:[]}});const rows=finalize([...firstRows.map((q,i)=>toArchiveRow(q,0,i)),...rest.flatMap(x=>x.rows.map((q,i)=>toArchiveRow(q,x.page,i)))].filter(Boolean),y);if(expected>0&&rows.length<Math.min(expected,Math.floor(expected*.9)))throw new Error(`Koşu Sorgulama sayfalama doğrulaması başarısız (${rows.length}/${expected}).`);status(`${y}: ${rows.length} gerçekleşmiş yarış yerel arşive yazılıyor…`,92);await replaceYear(y,rows);status(`${y} tamamlandı: ${rows.length} gerçekleşmiş yarış · kaynak Koşu Sorgulama.`,100);try{await window.ATAnnualArchiveV13?.refreshMeta?.(true)}catch{}renameMenu()}catch(e){status(`${y} güncellenemedi: ${e?.message||e}`,0)}finally{if(btn)btn.disabled=false}}
const dayCache=new Map();
async function actualDay(row){const k=`${row.date}|${row.cityId}|${row.city}`;if(dayCache.has(k))return dayCache.get(k);const u=new URL('/api/tjk-day-results-v1',location.origin);u.searchParams.set('date',row.date);u.searchParams.set('city',row.city);if(row.cityId)u.searchParams.set('cityId',String(row.cityId));u.searchParams.set('_at',String(Date.now()));const d=await fetchJson(u.pathname+u.search),races=Array.isArray(d?.races)?d.races:[];dayCache.set(k,races);return races}
function sameRace(row,r){const c=parseClass(r?.class||r?.yaradi1||'');return c.classKey===row.classKey&&ageKey(r?.ageGroup||r?.yaradi2||'')===ageKey(row.groupRaw)&&Number(r?.distance||r?.mesafe||0)===Number(row.distance)&&trackKey(r?.track||r?.pist||'')===row.trackKey}
function raceWinner(r){return clean(r?.winner?.horseName||r?.winner?.name||r?.winnerHorse||r?.top3?.[0]?.horseName||r?.rows?.find?.(x=>Number(x?.finish)===1)?.horseName||'')}
async function resolveSelectedActual(){const ids=window.ATAnnualArchiveV13?.getSelectedIds?.()||[];if(!ids.length){status('Önce en az bir yarış seçin.',null);return}let done=0,resolved=0;for(const id of ids){const row=await window.ATAnnualArchiveV13?.getRow?.(id);if(!row)continue;try{const races=await actualDay(row),candidates=races.filter(r=>sameRace(row,r));let pick=null;if(candidates.length===1)pick=candidates[0];else if(candidates.length>1&&row.queryWinner){pick=candidates.find(r=>key(raceWinner(r))===key(row.queryWinner))||null}if(pick){row.raceNo=Number(pick.no||pick.raceNo||0)||0;row.permanentKey=`${row.date}|${row.cityId}|${row.raceNo}`;row.resolutionMethod='EXACT_DAILY_RESULT';row.candidateRaceNos=[];await putRow(row);resolved++;const cb=document.querySelector(`[data-select="${CSS.escape(String(id))}"]`),card=cb?.closest?.('.aa-row');if(card){const last=card.lastElementChild;if(last)last.innerHTML=`<span class="aa-resolved">${row.raceNo}.K ✓</span>`}}else{row.candidateRaceNos=candidates.map(r=>Number(r.no||r.raceNo||0)).filter(Boolean);await putRow(row)}}catch(e){row.resolveError=e?.message||String(e);await putRow(row)}done++;status(`Gerçek sonuçtan Koşu No çözümleme: ${done}/${ids.length} · ${resolved} çözüldü`,null)} }
function clickCapture(e){renameMenu();const t=e.target?.closest?.('#aaUpdateYear,#aaResolve');if(!t)return;if(t.id==='aaUpdateYear'){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();const y=Number(document.getElementById('aaUpdateYearSelect')?.value||0);updateYearFromQuery(y);return}if(t.id==='aaResolve'){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();resolveSelectedActual();return}}
function install(){renameMenu();document.addEventListener('click',clickCapture,true);window.ATAnnualQuerySourceF60943134={version:VERSION,updateYear:updateYearFromQuery,resolveSelected:resolveSelectedActual};console.info('[AT AI]',VERSION,'aktif — Yıllık Yarış Arşivi listesi Koşu Sorgulama; Koşu No gerçek günlük sonuçlardan.');}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
